package me.snowsun.tabprefix.test;

import com.google.gson.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import javax.imageio.ImageIO;
import me.snowsun.tabprefix.config.PluginSettings;
import me.snowsun.tabprefix.domain.*;
import me.snowsun.tabprefix.infrastructure.media.MediaStore;
import me.snowsun.tabprefix.infrastructure.resourcepack.*;

/** Independent PNG/bitmap metrics, Unicode budgets and delivered-pack overlays. */
public final class ArtworkIntegrationTest {
  static int checks;
  static void check(boolean v,String why){if(!v)throw new AssertionError(why);checks++;}
  static JsonObject copy(JsonObject j){return new JsonParser().parse(j.toString()).getAsJsonObject();}
  static void reject(Runnable work){try{work.run();throw new AssertionError("Invalid artwork accepted");}catch(IllegalArgumentException expected){checks++;}}
  static JsonObject box(String surface,int index,int width,int height){JsonObject j=new JsonObject();j.addProperty("surface",surface);j.addProperty("index",index);j.addProperty("width",width);j.addProperty("height",height);j.addProperty("adaptive",false);return j;}
  static JsonObject shape(String id,String kind,int x,int y,int w,int h,String fill){JsonObject j=new JsonObject();j.addProperty("id",id);j.addProperty("kind",kind);j.addProperty("x",x);j.addProperty("y",y);j.addProperty("width",w);j.addProperty("height",h);JsonObject p=new JsonObject();p.addProperty("fill",fill);p.addProperty("end",fill);p.addProperty("opacity",100);j.add("paint",p);return j;}
  static JsonObject point(int x,int y){JsonObject j=new JsonObject();j.addProperty("x",x);j.addProperty("y",y);return j;}
  static JsonObject document(){JsonObject j=DisplayDesign.defaults(false).json();j.addProperty("sidebarEnabled",true);j.addProperty("sidebarMode","HUD");j.addProperty("headerEnabled",true);j.addProperty("footerEnabled",true);JsonObject art=j.getAsJsonObject("artwork");JsonArray boxes=new JsonArray();boxes.add(box("HEADER",0,240,26));boxes.add(box("FOOTER",0,160,35));boxes.add(box("CELL",0,120,8));art.add("boxes",boxes);JsonArray shapes=new JsonArray();shapes.add(shape("rectangle","RECT",10,12,40,20,"#ff0000"));shapes.add(shape("ellipse","ELLIPSE",60,12,20,20,"#00ff00"));JsonObject polygon=shape("polygon","POLYGON",90,12,30,20,"#0000ff");JsonArray points=new JsonArray();points.add(point(0,1000));points.add(point(500,0));points.add(point(1000,1000));polygon.add("points",points);shapes.add(polygon);art.add("shapes",shapes);return j;}
  static void input(){JsonObject j=document();DisplayDesign d=new DisplayDesign(j);check(new DisplayDesign(d.json()).json().equals(d.json()),"canonical artwork round trip");check(d.artwork.box("CELL",0).height==8,"native TAB row height");check(d.artwork.box("HEADER",0).extraLines()==2,"banner reserves following lines");check(d.artwork.rowY(d,1)==d.sidebarY+2*d.sidebarLineHeight,"legacy row positions preserved");check(d.artwork.row(-1).x==7,"legacy panel padding");try{d.artwork.shapes.clear();throw new AssertionError();}catch(UnsupportedOperationException expected){checks++;}
    for(String field:new String[]{"width","height","padding"}){JsonObject bad=copy(j);bad.getAsJsonObject("artwork").getAsJsonArray("boxes").get(2).getAsJsonObject().addProperty(field,field.equals("height")?9:field.equals("padding")?100:0);reject(()->new DisplayDesign(bad));}
    JsonObject missing=copy(j);missing.getAsJsonObject("artwork").getAsJsonArray("boxes").get(0).getAsJsonObject().addProperty("index",11);reject(()->new DisplayDesign(missing));
    JsonObject bad=copy(j);JsonObject invalid=bad;bad.getAsJsonObject("artwork").getAsJsonArray("shapes").get(2).getAsJsonObject().getAsJsonArray("points").get(0).getAsJsonObject().addProperty("x",1001);reject(()->new DisplayDesign(invalid));
    JsonObject duplicate=copy(j);duplicate.getAsJsonObject("artwork").getAsJsonArray("shapes").add(copy(duplicate.getAsJsonObject("artwork").getAsJsonArray("shapes").get(0).getAsJsonObject()));reject(()->new DisplayDesign(duplicate));
    JsonObject unsafe=copy(j);unsafe.getAsJsonObject("artwork").getAsJsonObject("panel").addProperty("fill","url(http://bad)");reject(()->new DisplayDesign(unsafe));
    JsonObject orphan=copy(j);orphan.getAsJsonObject("artwork").getAsJsonArray("shapes").get(0).getAsJsonObject().addProperty("surface","HEADER");orphan.getAsJsonObject("artwork").getAsJsonArray("shapes").get(0).getAsJsonObject().addProperty("index",1);reject(()->new DisplayDesign(orphan));
    check(ArtworkText.tab(NativeHudLayout.EMPTY,d,"HEADER",0,"Plain").equals("Plain"),"no private glyphs before delivery");
  }
  static void pixels(){DisplayDesign d=new DisplayDesign(document());BufferedImage image=ArtworkRasterizer.render(d,null);check(image.getWidth()==180,"panel width");check(image.getRGB(15,15)==0xffff0000,"rectangle exact pixels");check(image.getRGB(70,22)==0xff00ff00,"ellipse exact center");check(image.getRGB(60,12)!=0xff00ff00,"ellipse transparent corner");check(image.getRGB(105,25)==0xff0000ff,"arbitrary polygon interior");check(image.getRGB(90,13)!=0xff0000ff,"polygon exterior");
    JsonObject j=document();JsonObject p=j.getAsJsonObject("artwork").getAsJsonObject("panel");p.addProperty("fill","#000000");p.addProperty("end","#ffffff");p.addProperty("opacity",50);p.addProperty("accentWidth",0);j.getAsJsonObject("artwork").add("shapes",new JsonArray());image=ArtworkRasterizer.render(new DisplayDesign(j),null);check((image.getRGB(80,40)>>>24)==128,"configured alpha");check((image.getRGB(80,110)&255)>(image.getRGB(80,10)&255),"gradient runs vertically");
    j=document();JsonArray shapes=j.getAsJsonObject("artwork").getAsJsonArray("shapes");JsonObject path=shape("path","PATH",0,50,100,20,"none"),paint=path.getAsJsonObject("paint");paint.addProperty("stroke","#ff00ff");paint.addProperty("strokeWidth",2);path.addProperty("closed",false);JsonArray points=new JsonArray();points.add(point(0,0));points.add(point(1000,1000));path.add("points",points);shapes.add(path);image=ArtworkRasterizer.render(new DisplayDesign(j),null);check((image.getRGB(50,60)&0xffffff)==0xff00ff,"freehand stroke rasterized");
  }
  static void drawing(){
    JsonObject j=DisplayDesign.defaults(false).json();j.addProperty("sidebarBackground",false);
    JsonObject path=shape("drawing","PATH",20,20,100,60,"none");path.addProperty("closed",false);
    path.getAsJsonObject("paint").addProperty("stroke","#ff00ff");path.getAsJsonObject("paint").addProperty("strokeWidth",2);
    JsonArray points=new JsonArray();points.add(point(0,0));points.add(point(1000,0));JsonObject begin=point(0,1000);begin.addProperty("move",true);points.add(begin);points.add(point(1000,1000));path.add("points",points);
    JsonArray shapes=new JsonArray();shapes.add(path);j.getAsJsonObject("artwork").add("shapes",shapes);
    DisplayDesign d=new DisplayDesign(j);BufferedImage image=ArtworkRasterizer.render(d,null);
    check((image.getRGB(70,20)&0xffffff)==0xff00ff,"first disconnected stroke is painted");
    check((image.getRGB(70,80)&0xffffff)==0xff00ff,"second disconnected stroke is painted");
    check(image.getRGB(70,50)==0,"no diagonal bridge between separate strokes");
    check(new DisplayDesign(d.json()).artwork.shapes.get(0).points.get(2).move,"stroke break survives serialization and restart");
    points=new JsonArray();for(int i=0;i<6000;i++)points.add(point(i%1001,(i/1001)*100));path.add("points",points);
    d=new DisplayDesign(j);check(d.artwork.shapes.get(0).points.size()==6000,"drawing has no 50 or 96 point cap");
    check(new DisplayDesign(d.json()).artwork.shapes.get(0).points.size()==6000,"large drawing round trip preserves every point");
    check(ArtworkRasterizer.render(d,null).getWidth()==d.sidebarWidth,"large drawing rasterizes successfully");
  }
  static Map<Integer,Integer> metrics(ZipFile z)throws Exception {Map<Integer,Integer> result=new HashMap<>();JsonObject font;try(Reader in=new InputStreamReader(z.getInputStream(z.getEntry("assets/minecraft/font/default.json")),"UTF-8")){font=new JsonParser().parse(in).getAsJsonObject();}for(JsonElement e:font.getAsJsonArray("providers")){JsonObject p=e.getAsJsonObject();if(p.get("type").getAsString().equals("space")){for(Map.Entry<String,JsonElement> a:p.getAsJsonObject("advances").entrySet())result.put(a.getKey().codePointAt(0),a.getValue().getAsInt());continue;}if(!p.has("file"))continue;String file=p.get("file").getAsString().replace("tabprefix:","assets/tabprefix/textures/");BufferedImage image;try(InputStream in=z.getInputStream(z.getEntry(file))){image=ImageIO.read(in);}JsonArray rows=p.getAsJsonArray("chars");int cols=rows.get(0).getAsString().codePointCount(0,rows.get(0).getAsString().length()),cw=image.getWidth()/cols,ch=image.getHeight()/rows.size();check(cw<=256&&ch<=256||file.endsWith("hud-space.png"),"client texture cell limit");check(p.get("ascent").getAsInt()<=p.get("height").getAsInt(),"legal bitmap ascent");for(int y=0;y<rows.size();y++){int[] codes=rows.get(y).getAsString().codePoints().toArray();for(int x=0;x<cols;x++){if(codes[x]==0)continue;int ink=0;outer:for(int c=cw-1;c>=0;c--)for(int r=0;r<ch;r++)if((image.getRGB(x*cw+c,y*ch+r)>>>24)!=0){ink=c+1;break outer;}result.put(codes[x],(int)(.5f+ink*p.get("height").getAsFloat()/ch)+1);}}}return result;}
  static int width(String line,Map<Integer,Integer> metrics){int w=0;boolean bold=false;for(int n=0;n<line.length();){int c=line.codePointAt(n);n+=Character.charCount(c);if(c=='§'){char code=line.charAt(n++);if(code=='x'){n+=12;bold=false;}else if(code=='l')bold=true;else if(code=='r'||"0123456789abcdef".indexOf(code)>=0)bold=false;continue;}if(c==' ')w+=4;else {check(metrics.containsKey(c),"rendered glyph has measured pixels");w+=metrics.get(c)+(bold?1:0);}}return w;}
  static void pack(Path project,String version,boolean maximal)throws Exception {Path root=Files.createTempDirectory(project.resolve(".build/test-data"),"art-");PluginSettings cfg=HdVersionsIntegrationTest.settings(root,MinecraftVersion.parse(version));JsonObject j=document();if(maximal){while(j.getAsJsonArray("sidebar").size()<15)j.getAsJsonArray("sidebar").add(new JsonObject());JsonObject a=j.getAsJsonObject("artwork");JsonArray boxes=new JsonArray();for(int i=0;i<80;i++)boxes.add(box("CELL",i,120,8));for(String surface:new String[]{"HEADER","FOOTER"}){JsonArray lines=new JsonArray();for(int n=0;n<12;n++){JsonObject line=new JsonObject();line.addProperty("text","Line "+n);lines.add(line);boxes.add(box(surface,n,240,32));}j.add(surface.toLowerCase(Locale.ROOT),lines);}a.add("boxes",boxes);JsonArray screens=new JsonArray();j.addProperty("screenEnabled",true);for(int n=0;n<12;n++){JsonObject screen=new JsonObject();screen.addProperty("id","screen-"+n);screen.addProperty("anchor","FREE_XY");screen.addProperty("y",-80-n);screens.add(screen);}j.add("screen",screens);}
    DisplayDesign d=new DisplayDesign(j);PackBuilder builder=new PackBuilder(cfg,new MediaStore(cfg),cfg.minecraft,"http://127.0.0.1:8999");builder.designs(()->d);PackRevision revision=builder.build(GraphicSnapshot.empty());if(!cfg.minecraft.bitmapFonts()){check(!revision.hud.present(),"1.12 plain fallback");check(ArtworkText.tab(revision.hud,d,"HEADER",0,"Fallback").equals("Fallback"),"1.12 has no private banner payload");return;}
    check(revision.hud.matches(d),"all profiles match document "+version);check(builder.load(GraphicSnapshot.empty()).hud.matches(d),"artwork survives pack metadata reload");Set<Integer> codes=new HashSet<>();for(NativeHudLayout.Profile p:revision.hud.profiles.values())for(int n=0;n<p.frames();n++){if(!codes.add(p.base+n)){NativeHudLayout.Profile shared=revision.hud.profiles.values().stream().filter(v->v!=p&&v.base==p.base).findFirst().get();check(p.image.isEmpty()&&shared.image.isEmpty()&&p.y==shared.y&&p.height==shared.height&&p.advance(n)==shared.advance(n),"shared text has identical metrics");}else check(true,"distinct glyph range");check(p.base+n<NativeHudLayout.SPACE,"spacer range reserved");}
    JsonObject changed=copy(j);changed.getAsJsonObject("artwork").getAsJsonObject("panel").addProperty("fill","#112233");check(!revision.hud.matches(new DisplayDesign(changed)),"stale background colors rejected");changed=copy(j);changed.getAsJsonObject("artwork").getAsJsonArray("shapes").get(0).getAsJsonObject().addProperty("x",11);check(!revision.hud.matches(new DisplayDesign(changed)),"stale shape positions rejected");changed=copy(j);changed.getAsJsonObject("artwork").getAsJsonObject("title").addProperty("y",16);check(!revision.hud.matches(new DisplayDesign(changed)),"stale text positions rejected");changed=copy(j);changed.addProperty("sidebarX",20);check(revision.hud.matches(new DisplayDesign(changed)),"moving entire panel reuses pack");
    try(ZipFile zip=new ZipFile(revision.file.toFile())){Map<Integer,Integer> metrics=metrics(zip);for(NativeHudLayout.Profile p:revision.hud.profiles.values())for(int n=0;n<p.frames();n++)check(metrics.get(p.base+n)==p.advance(n),"metadata advances equal client bitmap metrics");String banner=ArtworkText.tab(revision.hud,d,"HEADER",0,"§aHello §lМир 123");String[] lines=banner.split("\\n");check(lines.length==d.artwork.box("HEADER",0).extraLines()+1,"banner line reservations");check(width(lines[0],metrics)==240,"overlay has exact logical width");String cell=ArtworkText.tab(revision.hud,d,"CELL",0,"§lSome very long player name that must clip");check(!cell.contains("\n"),"TAB cell never changes native row height");check(width(cell,metrics)==120,"bold clipped text stays inside its cell");}
  }
  static void images(Path project)throws Exception {
    Path root=Files.createTempDirectory(project.resolve(".build/test-data"),"art-images-");PluginSettings cfg=HdVersionsIntegrationTest.settings(root,MinecraftVersion.parse("1.21.11"));
    UUID id=UUID.randomUUID();int w=cfg.features.cellWidth,h=cfg.features.cellHeight;Path assets=cfg.dataDirectory.resolve("assets").resolve(id.toString());Files.createDirectories(assets);BufferedImage image=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);for(int y=0;y<h;y++)for(int x=0;x<w;x++)image.setRGB(x,y,0xff6699cc);ImageIO.write(image,"png",assets.resolve("frame-0000.png").toFile());
    AssetDescriptor asset=new AssetDescriptor(id,"png",w,h,8,7,new int[]{2},new int[]{0xe000},1);GraphicSnapshot snapshot=new GraphicSnapshot(Collections.singletonMap(id,asset),Collections.emptyMap(),Collections.emptyMap());DisplayDesign d=new DisplayDesign(document());PackBuilder builder=new PackBuilder(cfg,new MediaStore(cfg),cfg.minecraft,"http://127.0.0.1:8999");builder.designs(()->d);PackRevision p=builder.build(snapshot);check(p.hud.foreignWidths.containsKey(0xe000),"image glyph metrics preserved for decorated cells");
    String line=ArtworkText.tab(p.hud,d,"CELL",0,"§f\ue000§r Image prefix");check(line.indexOf('\ue000')>=0,"custom image prefix remains an image");
    try(ZipFile zip=new ZipFile(p.file.toFile())){Map<Integer,Integer> metrics=metrics(zip);check(width(line,metrics)==120,"image and text overlay width matches actual bitmap pixels");}
    check(builder.load(snapshot).hud.foreignWidths.equals(p.hud.foreignWidths),"foreign image metrics survive restart");
  }
  public static void main(String[] args)throws Exception {Path project=Paths.get(args[0]);input();pixels();drawing();images(project);for(String version:new String[]{"1.12.2","1.13.2","1.19.4","1.21.11"})pack(project,version,false);pack(project,"1.21.11",true);System.out.println("PASS: "+checks+" artwork checks: vector pixels, boundaries, full layout glyph budget, bitmap metrics, banner spacing and text fallbacks.");}
}
